  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active)
  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ART','ELEMENTOS','CARTAZ_CULTURAL','Dois cartazes anunciam a mesma feira. No primeiro, o nome da feira ocupa o centro em letras grandes; no segundo, o nome aparece pequeno no rodapé e uma ilustração ocupa quase todo o espaço. Qual diferença de hierarquia visual é mais evidente?','["Os dois priorizam igualmente o nome da feira.","O primeiro destaca a informação verbal; o segundo prioriza a imagem.","O segundo usa necessariamente cores mais contrastantes.","O primeiro não possui composição porque contém texto."]'::jsonb,'"O primeiro destaca a informação verbal; o segundo prioriza a imagem."'::jsonb,'O tamanho e a posição orientam o percurso do olhar: no primeiro, o nome é o foco; no segundo, a ilustração recebe maior destaque.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-art-composition-01","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"CARTAZ_CULTURAL","error_focus":"Confundir a presença de elementos com a hierarquia que eles estabelecem.","remediation_hint":"Compare escala e posição dos elementos antes de concluir qual deles chama primeiro a atenção.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-art-composition-01') returning id into v_question_id;
  if v_question_id is null then
