  insert into public.learning_question_bank(package_type,source_type,source_name,subject_area,domain,topic,statement,options,correct_answer,explanation,difficulty,estimated_minutes,provenance,metadata,active)
  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ART','ELEMENTOS','DESENHO_DE_MOVIMENTO','Em uma composição, linhas diagonais convergem para uma pessoa em movimento. Em outra, linhas horizontais repetidas organizam figuras em repouso. Qual leitura compara melhor os efeitos das linhas?','["As diagonais podem sugerir direção e dinamismo; as horizontais tendem a organizar uma sensação de estabilidade.","Linhas diagonais sempre representam perigo e horizontais sempre representam paz.","As linhas não afetam a leitura quando há figuras humanas.","A segunda composição necessariamente possui mais profundidade."]'::jsonb,'"As diagonais podem sugerir direção e dinamismo; as horizontais tendem a organizar uma sensação de estabilidade."'::jsonb,'A orientação das linhas contribui para o ritmo e a direção do olhar, mas não determina sozinha um significado universal.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-art-composition-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"DESENHO_DE_MOVIMENTO","error_focus":"Transformar uma tendência visual em regra simbólica absoluta.","remediation_hint":"Descreva o efeito formal observável e evite atribuir um significado fixo sem considerar o conjunto.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-art-composition-02') returning id into v_question_id;
  if v_question_id is null then
    select id into v_question_id from public.learning_question_bank where active and source_type='TECESCOLA_V9_AUTHORED_V1' and metadata->>'content_id'='v9-art-composition-02' and statement='Em uma composição, linhas diagonais convergem para uma pessoa em movimento. Em outra, linhas horizontais repetidas organizam figuras em repouso. Qual leitura compara melhor os efeitos das linhas?' and options='["As diagonais podem sugerir direção e dinamismo; as horizontais tendem a organizar uma sensação de estabilidade.","Linhas diagonais sempre representam perigo e horizontais sempre representam paz.","As linhas não afetam a leitura quando há figuras humanas.","A segunda composição necessariamente possui mais profundidade."]'::jsonb and correct_answer='"As diagonais podem sugerir direção e dinamismo; as horizontais tendem a organizar uma sensação de estabilidade."'::jsonb and explanation='A orientação das linhas contribui para o ritmo e a direção do olhar, mas não determina sozinha um significado universal.' and difficulty='MEDIUM' and metadata='{"content_id":"v9-art-composition-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"DESENHO_DE_MOVIMENTO","error_focus":"Transformar uma tendência visual em regra simbólica absoluta.","remediation_hint":"Descreva o efeito formal observável e evite atribuir um significado fixo sem considerar o conjunto.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb;
