  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ART','ELEMENTOS','PALETA_CROMATICA','Uma capa usa poucas cores próximas entre si e baixo contraste. Outra combina fundo escuro com uma forma clara isolada. Qual comparação é sustentada pela descrição?','["A primeira não pode comunicar emoção por usar cores próximas.","A segunda é necessariamente mais equilibrada em qualquer contexto.","A segunda cria maior contraste local e tende a destacar a forma clara.","O fundo escuro torna impossível perceber a forma clara."]'::jsonb,'"A segunda cria maior contraste local e tende a destacar a forma clara."'::jsonb,'A diferença de luminosidade descrita aumenta o contraste e a saliência da forma clara, sem garantir por si só a qualidade global da composição.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-art-composition-04","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"PALETA_CROMATICA","error_focus":"Confundir destaque local com avaliação total da obra.","remediation_hint":"Relacione o contraste observado ao foco visual, sem concluir automaticamente que a composição é melhor.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-art-composition-04') returning id into v_question_id;
