  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ART','ELEMENTOS','ARQUITETURA_E_ESPACO','Uma praça representada em perspectiva tem caminhos que convergem para um ponto distante. Em uma planta vista de cima, os mesmos caminhos são traçados paralelamente e as áreas são codificadas por cores. Qual diferença de representação deve ser considerada?','["A planta mostra necessariamente o espaço em tamanho real.","A perspectiva é sempre mais precisa para medir áreas.","As cores da planta eliminam a informação espacial.","A perspectiva sugere profundidade por convergência; a planta privilegia relações de localização vistas de cima."]'::jsonb,'"A perspectiva sugere profundidade por convergência; a planta privilegia relações de localização vistas de cima."'::jsonb,'Os modos de representação atendem a propósitos diferentes: a perspectiva cria uma visão espacial com profundidade, enquanto a planta facilita localizar elementos no conjunto.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-art-composition-07","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"COMPARE","context_family":"ARQUITETURA_E_ESPACO","error_focus":"Supor que toda representação visual comunica as mesmas relações espaciais.","remediation_hint":"Pergunte qual ponto de vista foi adotado e qual informação cada forma torna mais legível.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-art-composition-07') returning id into v_question_id;
