  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ART','ELEMENTOS','FOCO_E_NEGATIVO','Em um desenho, uma pequena janela iluminada aparece no centro de uma fachada escura; em outro, muitas janelas recebem iluminação semelhante. Qual afirmação descreve melhor o foco visual do primeiro?','["A janela prova que a cena ocorre durante o dia.","A fachada escura impede que qualquer outro elemento seja percebido.","O contraste entre a janela clara e a fachada escura tende a concentrar o olhar naquela área.","O centro geométrico é sempre o único foco possível."]'::jsonb,'"O contraste entre a janela clara e a fachada escura tende a concentrar o olhar naquela área."'::jsonb,'O contraste de luminosidade torna a janela mais saliente, embora contexto e outros elementos também possam orientar a leitura.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-art-composition-13","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ART_COMPARE_COMPOSITIONS","purpose":"REVIEW","difficulty":"MEDIUM","cognitive_process":"EXPLAIN","context_family":"FOCO_E_NEGATIVO","error_focus":"Transformar uma pista visual em certeza sobre a narrativa representada.","remediation_hint":"Explique como a relação entre claro e escuro afeta a atenção, sem inferir fatos que a descrição não fornece.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-art-composition-13') returning id into v_question_id;
