  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','ORGANELAS','Células musculares costumam demandar muita energia para contração. Qual relação entre estrutura e função ajuda a explicar a presença abundante de mitocôndrias nesses tecidos?','["Mitocôndrias guardam todo o DNA e comandam diretamente cada contração.","Mitocôndrias fabricam glicose a partir de luz nas células musculares.","Mitocôndrias participam da respiração celular e contribuem para a produção de ATP utilizado em processos celulares.","Mitocôndrias impedem a passagem de íons pela membrana."]'::jsonb,'"Mitocôndrias participam da respiração celular e contribuem para a produção de ATP utilizado em processos celulares."'::jsonb,'A demanda energética elevada é compatível com maior presença de organelas associadas à respiração celular e à produção de ATP; isso não significa que a mitocôndria execute sozinha a contração.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"ORGANELAS","error_focus":"Atribuir a uma organela toda a função do tecido.","remediation_hint":"Associe a organela ao processo celular que ela sustenta e diferencie isso da função integrada do tecido.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-biology-cell-02') returning id into v_question_id;
