  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','CELULA_VEGETAL','Uma planta perde turgor após ficar em uma solução muito concentrada. Qual explicação relaciona o movimento de água à estrutura celular?','["A parede celular bombeia água para fora usando ATP em qualquer condição.","A água tende a sair da célula para o meio mais concentrado, reduzindo o volume do conteúdo celular e a pressão de turgor.","A água atravessa apenas o núcleo e dissolve a parede celular.","A solução concentrada faz a célula produzir água por fotossíntese no escuro."]'::jsonb,'"A água tende a sair da célula para o meio mais concentrado, reduzindo o volume do conteúdo celular e a pressão de turgor."'::jsonb,'Na osmose, a água atravessa uma membrana semipermeável em resposta a diferenças de potencial hídrico; a parede celular limita a expansão, mas não bombeia água.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-03","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"CELULA_VEGETAL","error_focus":"Trocar a direção do movimento de água ou atribuir transporte ativo à parede celular.","remediation_hint":"Compare a concentração dos meios e acompanhe a água, não o soluto, através da membrana.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-biology-cell-03') returning id into v_question_id;
