  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','CELULAS_PROCARIONTES','Uma amostra possui células sem núcleo delimitado por membrana e sem organelas membranosas, mas com ribossomos e material genético. Qual classificação é compatível com essas observações?','["Procarionte, pois a ausência de núcleo membranoso é uma característica definidora desse tipo celular.","Eucarionte, porque toda célula com DNA possui núcleo.","Acelular, porque ribossomos não são estruturas celulares.","Animal, pois células animais não possuem material genético."]'::jsonb,'"Procarionte, pois a ausência de núcleo membranoso é uma característica definidora desse tipo celular."'::jsonb,'Células procarióticas possuem DNA e ribossomos, mas não apresentam núcleo delimitado por membrana nem organelas membranosas típicas de eucariontes.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-04","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"CELULAS_PROCARIONTES","error_focus":"Tratar material genético e núcleo como sinônimos.","remediation_hint":"Verifique se o DNA está delimitado por um envelope nuclear e quais estruturas membranosas foram observadas.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-biology-cell-04') returning id into v_question_id;
