  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','PRODUCAO_DE_PROTEINAS','Uma célula secreta grande quantidade de uma proteína. Qual sequência descreve de modo mais adequado o papel de estruturas envolvidas na produção e no encaminhamento dessa proteína?','["Lisossomos transcrevem o DNA e a membrana nuclear secreta a proteína pronta.","Mitocôndrias traduzem o RNA e cloroplastos empacotam a proteína em vesículas.","O complexo golgiense copia genes e os ribossomos armazenam a proteína fora da célula.","Ribossomos sintetizam a cadeia; o retículo endoplasmático rugoso participa do processamento inicial; o complexo golgiense modifica e encaminha produtos de secreção."]'::jsonb,'"Ribossomos sintetizam a cadeia; o retículo endoplasmático rugoso participa do processamento inicial; o complexo golgiense modifica e encaminha produtos de secreção."'::jsonb,'A produção envolve ribossomos e o sistema de endomembranas; a rota exata depende do tipo de proteína, mas a opção descreve corretamente a via secretora geral.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-05","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"PRODUCAO_DE_PROTEINAS","error_focus":"Confundir síntese proteica, processamento e transporte como uma única etapa ou estrutura.","remediation_hint":"Separe a sequência em síntese, processamento e encaminhamento e associe cada etapa à estrutura adequada.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-biology-cell-05') returning id into v_question_id;
