  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','TRANSPORTE_DE_MEMBRANA','Uma molécula pequena e apolar atravessa a bicamada lipídica a favor de seu gradiente, sem consumo direto de ATP. Qual mecanismo é mais compatível com a descrição?','["Transporte ativo contra o gradiente.","Endocitose de uma vesícula grande.","Difusão simples através da membrana.","Síntese da molécula dentro do núcleo."]'::jsonb,'"Difusão simples através da membrana."'::jsonb,'Moléculas pequenas e apolares podem atravessar a bicamada por difusão simples, seguindo o gradiente sem gasto direto de ATP.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-06","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"TRANSPORTE_DE_MEMBRANA","error_focus":"Classificar todo transporte pela membrana como ativo ou mediado por vesículas.","remediation_hint":"Use tamanho, polaridade, direção do gradiente e necessidade de energia para escolher o mecanismo.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
