  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','COMPARTIMENTALIZACAO','Uma enzima funciona melhor em meio ácido dentro de um compartimento celular. Por que a compartimentalização pode ser importante para essa função?','["Mantém condições locais adequadas e separa reações que poderiam ser incompatíveis com o citosol.","Faz com que todas as reações da célula ocorram no mesmo pH.","Impede completamente qualquer troca entre compartimentos.","Substitui a necessidade de enzimas específicas."]'::jsonb,'"Mantém condições locais adequadas e separa reações que poderiam ser incompatíveis com o citosol."'::jsonb,'Compartimentos celulares criam microambientes e organizam reações; eles permanecem regulados e não são necessariamente isolados de toda troca.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-11","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"ANALYZE","context_family":"COMPARTIMENTALIZACAO","error_focus":"Interpretar compartimentalização como isolamento absoluto ou uniformidade química.","remediation_hint":"Relacione o ambiente local à atividade da enzima e reconheça que as trocas continuam reguladas.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
