  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','BIOLOGY','CELULA','CELULA_VEGETAL_E_ANIMAL','Uma célula possui parede de celulose, grande vacúolo central e cloroplastos; outra não apresenta essas estruturas, mas ambas possuem membrana plasmática, citoplasma e material genético. Qual comparação é adequada?','["A segunda não é célula porque não possui cloroplastos.","A primeira não possui membrana plasmática por ter parede celular.","A primeira tem características típicas de célula vegetal; as estruturas comuns também ocorrem na segunda.","Apenas células vegetais possuem material genético."]'::jsonb,'"A primeira tem características típicas de célula vegetal; as estruturas comuns também ocorrem na segunda."'::jsonb,'Parede de celulose, vacúolo central e cloroplastos são características vegetais; membrana, citoplasma e material genético são encontrados em ambos os tipos descritos.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-biology-cell-12","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"BIOLOGY_CELL_FUNCTION","purpose":"REVIEW","difficulty":"EASY","cognitive_process":"COMPARE","context_family":"CELULA_VEGETAL_E_ANIMAL","error_focus":"Confundir estruturas distintivas com estruturas universais da célula.","remediation_hint":"Separe características compartilhadas daquelas associadas a um tipo celular específico.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
