  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ENGLISH','LEITURA','SCHOOL_NOTICE','Read the notice: “The art room will be closed on Friday. Students should return borrowed brushes to room 12 by Thursday afternoon.” What should students do before Friday?','["Meet in the art room on Friday.","Return borrowed brushes by Thursday afternoon.","Borrow new brushes on Saturday.","Keep the brushes until next week."]'::jsonb,'"Return borrowed brushes by Thursday afternoon."'::jsonb,'The notice gives a deadline before the room closes; borrowed brushes must be returned by Thursday afternoon.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-english-reading-11","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ENGLISH_INFER_FROM_TEXT","purpose":"PROBE","difficulty":"EASY","cognitive_process":"INFER","context_family":"SCHOOL_NOTICE","error_focus":"Ignoring a deadline expressed in a different sentence.","remediation_hint":"Locate the action students must take and match it with the time limit.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
