  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ENGLISH','LEITURA','PUBLIC_TRANSPORT','Read: “Maya checked the bus app twice. When the second delay alert appeared, she sent her group a message: ‘Start without me; I’ll join online.’” Why did Maya send the message?','["She expected to arrive too late for the in-person meeting.","She wanted the group to cancel the project.","The bus app asked her to send a message.","She had already reached the meeting room."]'::jsonb,'"She expected to arrive too late for the in-person meeting."'::jsonb,'Repeated delay alerts and her plan to join online support the inference that she would not arrive on time.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-english-reading-12","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ENGLISH_INFER_FROM_TEXT","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"INFER","context_family":"PUBLIC_TRANSPORT","error_focus":"Choosing an option that repeats a detail but does not explain the action.","remediation_hint":"Connect the delay alerts with the change in how she will participate.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
