  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','ENGLISH','LEITURA','NEWS_LITERACY','Read: “The headline says ‘All local buses are free.’ The article explains that fares are suspended only on routes serving the festival area, from 5 p.m. to midnight.” Which interpretation is accurate?','["Every bus is free all day throughout the region.","Only festival staff can use the buses.","The headline is broader than the details: the fare suspension is limited by route and time.","The article says fares increase after 5 p.m."]'::jsonb,'"The headline is broader than the details: the fare suspension is limited by route and time."'::jsonb,'The body narrows the claim to particular routes and a specific time window, so the headline overgeneralizes.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-english-reading-20","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"ENGLISH_INFER_FROM_TEXT","purpose":"LOCK_IN","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"NEWS_LITERACY","error_focus":"Relying on a headline without checking the conditions in the article.","remediation_hint":"Compare broad claims with the precise limits given in the supporting text.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
