  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','GEOGRAPHY','TERRITORIO','ACESSO_A_SERVICOS','Dois setores urbanos têm população semelhante. No setor A, há escola, posto de saúde e linha frequente de ônibus; no setor B, esses serviços ficam distantes e o transporte passa poucas vezes ao dia. Qual desigualdade espacial é indicada?','["Diferença no acesso territorial a serviços e mobilidade.","Diferença de população total, que o enunciado afirma ser semelhante.","Diferença de clima necessariamente causada pelo transporte.","Ausência de qualquer relação entre localização e oportunidades."]'::jsonb,'"Diferença no acesso territorial a serviços e mobilidade."'::jsonb,'Mesmo com população semelhante, a distribuição e a acessibilidade dos serviços variam entre setores e podem produzir oportunidades desiguais.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-geo-territory-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"GEOGRAPHY_INTERPRET_TERRITORY","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"ACESSO_A_SERVICOS","error_focus":"Confundir quantidade de moradores com igualdade de acesso.","remediation_hint":"Compare distância, frequência e localização dos serviços, não apenas o tamanho da população.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
