  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','GEOGRAPHY','TERRITORIO','PRODUCAO_AGRICOLA','Uma região substitui cultivos variados por uma monocultura voltada à exportação. A produção total cresce, mas pequenos produtores passam a depender de poucos compradores. Qual análise territorial é mais completa?','["A mudança combina especialização produtiva com possível concentração de poder na cadeia de comercialização.","O aumento da produção prova que toda a população local se beneficiou igualmente.","A exportação elimina relações entre agricultura e mercado.","A dependência de compradores é uma característica física do solo."]'::jsonb,'"A mudança combina especialização produtiva com possível concentração de poder na cadeia de comercialização."'::jsonb,'A interpretação relaciona uso do território, organização da produção e relações de mercado sem presumir distribuição igual dos benefícios.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-geo-territory-06","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"GEOGRAPHY_INTERPRET_TERRITORY","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"PRODUCAO_AGRICOLA","error_focus":"Avaliar a transformação apenas pelo volume produzido.","remediation_hint":"Inclua na análise quem controla etapas da cadeia e como benefícios e riscos são distribuídos.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-geo-territory-06') returning id into v_question_id;
