    select id into v_question_id from public.learning_question_bank where active and source_type='TECESCOLA_V9_AUTHORED_V1' and metadata->>'content_id'='v9-geo-territory-07' and statement='Em uma metrópole, empregos formais se concentram em uma área central, enquanto moradias de menor custo se expandem na periferia. Mesmo com distância em linha reta moderada, viagens levam muito tempo por falta de conexões transversais. Qual fator explica melhor a experiência descrita?' and options='["A distância em linha reta determina sozinha o tempo de viagem.","A periferia necessariamente não possui moradores que trabalham no centro.","O tempo de deslocamento não depende de infraestrutura ou localização.","A estrutura da rede e a distribuição desigual de atividades podem ampliar o tempo de deslocamento para além da distância geométrica."]'::jsonb and correct_answer='"A estrutura da rede e a distribuição desigual de atividades podem ampliar o tempo de deslocamento para além da distância geométrica."'::jsonb and explanation='Acessibilidade depende de conectividade e localização, não apenas da distância euclidiana; desigualdades de uso do solo e transporte moldam os deslocamentos.' and difficulty='HARD' and metadata='{"content_id":"v9-geo-territory-07","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"GEOGRAPHY_INTERPRET_TERRITORY","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"COMPARE","context_family":"SEGREGACAO_RESIDENCIAL","error_focus":"Usar distância linear como medida completa de acessibilidade.","remediation_hint":"Considere o percurso possível, a rede disponível e onde moradia e emprego estão distribuídos.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb;
