  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','GEOGRAPHY','TERRITORIO','ENERGIA_E_TERRITORIO','Uma usina solar é instalada em uma área rural conectada à rede elétrica regional. A energia atende consumidores distantes, enquanto a área local recebe novas estradas e empregos temporários. Que leitura melhor considera diferentes escalas?','["A energia só pode ser consumida no município onde os painéis estão instalados.","A estrada prova que os empregos temporários serão permanentes.","A produção conecta o território local a redes regionais, com efeitos econômicos e espaciais distribuídos de modo desigual no tempo.","Uma atividade regional não produz qualquer mudança local."]'::jsonb,'"A produção conecta o território local a redes regionais, com efeitos econômicos e espaciais distribuídos de modo desigual no tempo."'::jsonb,'A infraestrutura articula escalas e seus efeitos locais podem diferir dos benefícios da rede regional e mudar conforme as fases do projeto.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-geo-territory-08","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"GEOGRAPHY_INTERPRET_TERRITORY","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"ENERGIA_E_TERRITORIO","error_focus":"Reduzir uma infraestrutura a uma escala e ignorar a distribuição temporal dos efeitos.","remediation_hint":"Diferencie onde a instalação está, quem recebe a energia e quais efeitos locais são duradouros ou temporários.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-geo-territory-08') returning id into v_question_id;
  if v_question_id is null then
    select id into v_question_id from public.learning_question_bank where active and source_type='TECESCOLA_V9_AUTHORED_V1' and metadata->>'content_id'='v9-geo-territory-08' and statement='Uma usina solar é instalada em uma área rural conectada à rede elétrica regional. A energia atende consumidores distantes, enquanto a área local recebe novas estradas e empregos temporários. Que leitura melhor considera diferentes escalas?' and options='["A energia só pode ser consumida no município onde os painéis estão instalados.","A estrada prova que os empregos temporários serão permanentes.","A produção conecta o território local a redes regionais, com efeitos econômicos e espaciais distribuídos de modo desigual no tempo.","Uma atividade regional não produz qualquer mudança local."]'::jsonb and correct_answer='"A produção conecta o território local a redes regionais, com efeitos econômicos e espaciais distribuídos de modo desigual no tempo."'::jsonb and explanation='A infraestrutura articula escalas e seus efeitos locais podem diferir dos benefícios da rede regional e mudar conforme as fases do projeto.' and difficulty='MEDIUM' and metadata='{"content_id":"v9-geo-territory-08","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"GEOGRAPHY_INTERPRET_TERRITORY","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"ENERGIA_E_TERRITORIO","error_focus":"Reduzir uma infraestrutura a uma escala e ignorar a distribuição temporal dos efeitos.","remediation_hint":"Diferencie onde a instalação está, quem recebe a energia e quais efeitos locais são duradouros ou temporários.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb;
