  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','HISTORY','FONTES','CARTA_DE_TRABALHADOR','Uma carta de 1930, escrita por um trabalhador a um parente, descreve jornadas longas e menciona que o remetente evita criticar o empregador pelo nome. Qual questão ajuda a interpretar a fonte?','["Qual é a opinião de todos os trabalhadores da cidade.","Como o destinatário, a posição do autor e possíveis riscos de circulação influenciam o que foi escrito.","Por que toda carta privada deve ser considerada sem valor histórico.","Como a carta prova que as jornadas eram iguais em todas as fábricas."]'::jsonb,'"Como o destinatário, a posição do autor e possíveis riscos de circulação influenciam o que foi escrito."'::jsonb,'Autoria, destinatário e condições de produção podem orientar escolhas e silêncios da carta; ela não representa automaticamente todos os trabalhadores.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-history-evidence-03","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"HISTORY_INTERPRET_EVIDENCE","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"CARTA_DE_TRABALHADOR","error_focus":"Generalizar uma experiência individual para todo um grupo sem triangulação.","remediation_hint":"Considere a posição de quem escreve, para quem escreve e o que poderia ser arriscado registrar.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
