  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','HISTORY','FONTES','PATRIMONIO_LOCAL','Uma antiga estação ferroviária foi transformada em centro cultural. Moradores mais velhos a associam ao trabalho, enquanto jovens a conhecem sobretudo pelos eventos atuais. Qual abordagem histórica acolhe essas relações distintas?','["Documentar usos, memórias e transformações em diferentes períodos, contextualizando quem produz cada narrativa.","Escolher uma memória como verdadeira e eliminar as demais.","Presumir que a função atual explica toda a história do edifício.","Tratar o patrimônio como espaço sem relações sociais."]'::jsonb,'"Documentar usos, memórias e transformações em diferentes períodos, contextualizando quem produz cada narrativa."'::jsonb,'O lugar acumula usos e significados; registrar perspectivas diversas e situá-las no tempo permite analisar continuidades e mudanças.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-history-evidence-08","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"HISTORY_INTERPRET_EVIDENCE","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"APPLY","context_family":"PATRIMONIO_LOCAL","error_focus":"Reduzir o significado histórico de um lugar à função atual ou a uma memória única.","remediation_hint":"Organize relatos por período, grupo e uso e procure evidências para relacioná-los.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-history-evidence-08') returning id into v_question_id;
