  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHYSICAL_EDUCATION','CORPO','ARREMESSO','Dois estudantes arremessam uma bola leve. Um coordena apoio dos pés, rotação do tronco e ação do braço; o outro movimenta principalmente o antebraço. Qual análise é mais adequada?','["A coordenação de segmentos pode transferir e somar contribuições ao movimento, mas o resultado também depende da tarefa e da prática.","O movimento do tronco impede qualquer transferência de energia.","Apenas a força do antebraço determina o arremesso.","A técnica coordenada garante a mesma distância para todas as pessoas."]'::jsonb,'"A coordenação de segmentos pode transferir e somar contribuições ao movimento, mas o resultado também depende da tarefa e da prática."'::jsonb,'A cadeia de movimentos articula segmentos corporais; desempenho não depende de uma única parte nem é igual para todos os corpos e contextos.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-pe-movement-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PE_ANALYZE_MOVEMENT","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"ARREMESSO","error_focus":"Reduzir uma habilidade motora a um único segmento corporal ou a um resultado garantido.","remediation_hint":"Descreva a sequência e a contribuição de diferentes segmentos sem afirmar que ela determina sozinha o desempenho.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
