  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHYSICAL_EDUCATION','CORPO','ADAPTACAO_DE_JOGO','Uma turma adapta uma partida para incluir participantes com diferentes níveis de mobilidade. Qual proposta mantém desafio e participação sem pressupor que todos precisam executar o mesmo gesto?','["Retirar do jogo quem não executa o gesto padronizado.","Manter todas as regras mesmo que impeçam a participação.","Ajustar espaço, regras, equipamentos ou papéis em diálogo com os participantes e observar se o objetivo do jogo permanece significativo.","Oferecer um papel sem relação com o jogo e sem escolha ao participante."]'::jsonb,'"Ajustar espaço, regras, equipamentos ou papéis em diálogo com os participantes e observar se o objetivo do jogo permanece significativo."'::jsonb,'Adaptações podem preservar o desafio central e ampliar acesso; sua adequação depende da participação e do contexto, não de uma solução idêntica para todos.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-pe-movement-05","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PE_ANALYZE_MOVEMENT","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"ADAPTACAO_DE_JOGO","error_focus":"Confundir inclusão com simples presença ou com execução corporal uniforme.","remediation_hint":"Identifique o objetivo do jogo e ajuste barreiras sem retirar a agência dos participantes.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-pe-movement-05') returning id into v_question_id;
