  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHYSICAL_EDUCATION','CORPO','ALAVANCAS_CORPORAIS','Ao levantar uma mochila do chão, uma pessoa aproxima a carga do corpo e flexiona quadris e joelhos. Que princípio ajuda a explicar por que a posição da carga importa?','["A distância entre a carga e as articulações altera o braço de momento e as exigências mecânicas sobre o corpo.","A proximidade da carga elimina o peso gravitacional.","Flexionar articulações reduz a massa da mochila.","A postura não muda a distribuição de forças."]'::jsonb,'"A distância entre a carga e as articulações altera o braço de momento e as exigências mecânicas sobre o corpo."'::jsonb,'A posição da carga influencia os momentos de força; aproximá-la pode reduzir o braço de momento, embora a técnica adequada dependa de carga e pessoa.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-pe-movement-06","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PE_ANALYZE_MOVEMENT","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"ALAVANCAS_CORPORAIS","error_focus":"Supor que mudar a posição altera a massa ou elimina a gravidade.","remediation_hint":"Compare a distância da carga ao eixo articular e relacione-a ao momento de força.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
