  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHYSICAL_EDUCATION','CORPO','EQUILIBRIO_DINAMICO','Uma pessoa caminha sobre uma linha e ajusta braços e tronco quando o apoio muda. Qual conceito descreve melhor a manutenção do controle durante o deslocamento?','["Equilíbrio dinâmico, que envolve ajustes contínuos do corpo enquanto há movimento.","Equilíbrio estático, que exige ausência completa de movimento.","Imobilidade articular como única estratégia de controle.","Velocidade constante sem relação com o apoio."]'::jsonb,'"Equilíbrio dinâmico, que envolve ajustes contínuos do corpo enquanto há movimento."'::jsonb,'No equilíbrio dinâmico, o corpo ajusta postura e segmentos durante a ação para manter estabilidade relativa em movimento.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-pe-movement-10","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PE_ANALYZE_MOVEMENT","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"EQUILIBRIO_DINAMICO","error_focus":"Definir equilíbrio como ausência total de movimento.","remediation_hint":"Observe se os ajustes ocorrem enquanto o corpo se desloca ou em uma posição mantida.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
