  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHILOSOPHY','ARGUMENTO','PREMISSA_E_CONCLUSAO','Uma estudante argumenta: “A biblioteca deve ampliar o horário, pois muitos alunos só conseguem estudar depois das aulas.” Qual trecho apresenta a conclusão defendida?','["A biblioteca deve ampliar o horário.","Muitos alunos só conseguem estudar depois das aulas.","A biblioteca já ampliou o horário.","Todos os estudantes preferem estudar à noite."]'::jsonb,'"A biblioteca deve ampliar o horário."'::jsonb,'A conclusão é a proposta que o argumento pretende sustentar; a frase sobre a disponibilidade dos alunos funciona como razão.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-philosophy-argument-01","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PHILOSOPHY_EVALUATE_ARGUMENT","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"PREMISSA_E_CONCLUSAO","error_focus":"Confundir a razão apresentada com a conclusão do argumento.","remediation_hint":"Pergunte qual afirmação o autor quer que o leitor aceite ou adote.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
