  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHILOSOPHY','ARGUMENTO','GENERALIZACAO','Após conversar com três colegas que preferem aulas em grupo, alguém conclui que todos os estudantes aprendem melhor dessa maneira. Qual fragilidade é mais clara?','["A conclusão é falsa porque aulas em grupo nunca ajudam.","A conversa não pode fornecer qualquer informação.","A amostra pequena e não selecionada não sustenta uma generalização sobre todos os estudantes.","A preferência individual prova o desempenho escolar de cada pessoa."]'::jsonb,'"A amostra pequena e não selecionada não sustenta uma generalização sobre todos os estudantes."'::jsonb,'Três relatos podem indicar experiências, mas não bastam para concluir sobre uma população diversa sem método de amostragem e medidas pertinentes.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-philosophy-argument-02","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PHILOSOPHY_EVALUATE_ARGUMENT","purpose":"PROBE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"GENERALIZACAO","error_focus":"Confundir alguns exemplos com evidência representativa de todos.","remediation_hint":"Compare o alcance da conclusão com o tamanho, seleção e diversidade das evidências.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
