  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHILOSOPHY','ARGUMENTO','CONTRAEXEMPLO','Um argumento afirma: “Toda regra escolar limita a liberdade; portanto, nenhuma regra escolar pode ser justa.” Qual pergunta testa melhor a passagem da premissa à conclusão?','["Qual é a cor do regulamento impresso?","Quantas páginas tem o documento de regras?","A palavra liberdade aparece em outros textos?","É possível haver uma regra que limite uma ação e, ainda assim, proteja direitos ou condições justas para todos?"]'::jsonb,'"É possível haver uma regra que limite uma ação e, ainda assim, proteja direitos ou condições justas para todos?"'::jsonb,'Um contraexemplo plausível, como uma regra que impede agressões, pode mostrar que a premissa não basta para a conclusão universal.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-philosophy-argument-04","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PHILOSOPHY_EVALUATE_ARGUMENT","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"CONTRAEXEMPLO","error_focus":"Aceitar uma conclusão universal sem testar casos que desafiem a relação proposta.","remediation_hint":"Procure um caso que satisfaça a premissa, mas não a conclusão; avalie se ele enfraquece o argumento.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
