  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PHILOSOPHY','ARGUMENTO','ARGUMENTO_NORMATIVO','Uma proposta diz: “A escola deve oferecer material acessível porque igualdade de participação exige remover barreiras evitáveis.” Qual evidência se relaciona mais diretamente à justificativa?','["Uma avaliação mostra quais barreiras impedem estudantes de acessar as atividades e como recursos acessíveis reduzem essas barreiras.","Uma pesquisa pergunta qual cor de capa os estudantes preferem.","Um relato afirma que todos os materiais atuais são perfeitos.","Uma lista informa apenas quantas páginas tem cada material."]'::jsonb,'"Uma avaliação mostra quais barreiras impedem estudantes de acessar as atividades e como recursos acessíveis reduzem essas barreiras."'::jsonb,'A evidência relevante conecta barreiras e participação à razão normativa apresentada; outras informações podem ser verdadeiras, mas não sustentam diretamente a justificativa.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-philosophy-argument-05","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PHILOSOPHY_EVALUATE_ARGUMENT","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"ARGUMENTO_NORMATIVO","error_focus":"Confundir dado relacionado ao tema com dado pertinente à razão do argumento.","remediation_hint":"Relacione a evidência ao elo específico entre princípio, problema e proposta.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
