  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PORTUGUESE','ARGUMENTACAO','MOBILIDADE','Leia: “A escola deveria ampliar o bicicletário. Em uma consulta local, 68% dos estudantes que moram a até três quilômetros disseram que usariam bicicleta se houvesse local seguro para estacionar.” Qual trecho expressa a tese?','["A escola deveria ampliar o bicicletário.","A consulta foi realizada localmente.","68% dos estudantes foram consultados.","Os estudantes moram a até três quilômetros."]'::jsonb,'"A escola deveria ampliar o bicicletário."'::jsonb,'A tese é a posição defendida. Os demais elementos apresentam contexto ou evidência para sustentá-la.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-port-argument-09","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PORTUGUESE_ARGUMENT_EVIDENCE","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"MOBILIDADE","error_focus":"Confundir informação de apoio com a posição central do texto.","remediation_hint":"Pergunte qual afirmação o autor quer que o leitor aceite ou considere.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
