  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PORTUGUESE','ARGUMENTACAO','DADOS_PUBLICOS','Leia: “A praça deve receber iluminação. Em uma enquete online com 18 respostas, 16 participantes disseram evitar o local à noite.” Qual limite da evidência deve ser considerado?','["A enquete mede exatamente a luminosidade em lux.","As respostas comprovam que a iluminação causou todos os problemas relatados.","A amostra é pequena e voluntária, portanto pode não representar todos os usuários da praça.","O resultado é inválido apenas por ser expresso em números."]'::jsonb,'"A amostra é pequena e voluntária, portanto pode não representar todos os usuários da praça."'::jsonb,'A enquete informa a percepção dos respondentes, mas o tamanho e a seleção voluntária limitam a generalização.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-port-argument-14","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PORTUGUESE_ARGUMENT_EVIDENCE","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"DADOS_PUBLICOS","error_focus":"Tratar qualquer dado numérico como prova representativa.","remediation_hint":"Verifique quem respondeu, quantas pessoas participaram e qual conclusão o método permite.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
