  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PORTUGUESE','ARGUMENTACAO','ACESSIBILIDADE','Leia: “A sinalização da biblioteca deve incluir letras ampliadas. Em uma consulta acessível, quatro de seis estudantes com baixa visão relataram dificuldade para localizar os setores.” Qual é a relação entre as frases?','["A segunda contradiz necessariamente a primeira.","A segunda apresenta uma evidência ligada à necessidade defendida na primeira.","A primeira é um dado e a segunda é uma ordem.","As duas apresentam apenas informações sem relação argumentativa."]'::jsonb,'"A segunda apresenta uma evidência ligada à necessidade defendida na primeira."'::jsonb,'A proposta funciona como tese e os relatos de dificuldade oferecem uma razão pertinente para ela.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-port-argument-15","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PORTUGUESE_ARGUMENT_EVIDENCE","purpose":"TRANSFER","difficulty":"MEDIUM","cognitive_process":"ANALYZE","context_family":"ACESSIBILIDADE","error_focus":"Não reconhecer a ligação entre uma recomendação e a evidência que a motiva.","remediation_hint":"Pergunte se o segundo enunciado ajuda a justificar o primeiro.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
