  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PORTUGUESE','ARGUMENTACAO','SAUDE_ESCOLAR','Um texto defende instalar bebedouros e cita que “a maioria dos estudantes gosta de água gelada”. Qual dado sustentaria melhor a necessidade de mais pontos de água?','["Uma contagem dos locais disponíveis e do tempo de espera nos horários de maior uso.","Uma enquete sobre a cor preferida dos bebedouros.","A opinião de que água é importante para a vida.","O total de cartazes expostos no corredor."]'::jsonb,'"Uma contagem dos locais disponíveis e do tempo de espera nos horários de maior uso."'::jsonb,'A tese trata da quantidade e acesso aos pontos; disponibilidade e espera medem diretamente esse problema.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-port-argument-16","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PORTUGUESE_ARGUMENT_EVIDENCE","purpose":"TRANSFER","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"SAUDE_ESCOLAR","error_focus":"Confundir apoio genérico ao tema com evidência para a solução específica.","remediation_hint":"Escolha o dado que observa a condição que a proposta pretende mudar.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
