  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','PORTUGUESE','ARGUMENTACAO','CULTURA','Leia: “O sarau deve ocorrer em dois turnos. No evento anterior, estudantes que trabalhavam à tarde não puderam participar.” Qual alternativa identifica corretamente tese e evidência?','["Tese: estudantes trabalham à tarde; evidência: realizar o sarau.","Tese: houve evento anterior; evidência: o sarau deve ocorrer.","Tese e evidência são a mesma frase, sem funções distintas.","Tese: realizar o sarau em dois turnos; evidência: a ausência de participação de estudantes que trabalhavam à tarde."]'::jsonb,'"Tese: realizar o sarau em dois turnos; evidência: a ausência de participação de estudantes que trabalhavam à tarde."'::jsonb,'A recomendação é a posição defendida; a experiência anterior é a razão apresentada para ampliá-la.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-port-argument-17","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"PORTUGUESE_ARGUMENT_EVIDENCE","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitive_process":"INTERPRET","context_family":"CULTURA","error_focus":"Inverter a conclusão defendida e o fato usado para justificá-la.","remediation_hint":"Localize a proposta e, separadamente, a observação que levou a ela.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
