  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','SOCIOLOGY','INSTITUICOES','ESCOLA_E_NORMAS','Uma escola define horários, papéis de estudantes e professores e procedimentos para resolver conflitos. O que caracteriza sociologicamente esse conjunto?','["Uma instituição apenas quando todas as pessoas concordam com cada regra.","Um grupo sem história nem relação com outras instituições.","Uma estrutura natural que não pode mudar com a sociedade.","Uma instituição social que organiza relações, expectativas e práticas por meio de regras e papéis."]'::jsonb,'"Uma instituição social que organiza relações, expectativas e práticas por meio de regras e papéis."'::jsonb,'Instituições organizam práticas e expectativas relativamente estáveis, embora sejam vividas, contestadas e transformadas por pessoas e grupos.','EASY',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-sociology-institutions-01","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"SOCIOLOGY_EXPLAIN_INSTITUTIONS","purpose":"PROBE","difficulty":"EASY","cognitive_process":"IDENTIFY","context_family":"ESCOLA_E_NORMAS","error_focus":"Confundir instituição com prédio ou com consenso absoluto.","remediation_hint":"Procure regras, papéis e práticas recorrentes que organizam relações, não apenas o espaço físico.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
