  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','SOCIOLOGY','INSTITUICOES','MUDANCA_INSTITUCIONAL','Uma biblioteca passa a emprestar equipamentos digitais e cria regras de reserva, devolução e suporte. Qual interpretação mostra a adaptação institucional?','["A instituição incorpora uma nova prática e ajusta regras e papéis para organizar seu uso.","A biblioteca deixa de ser instituição porque mudou um serviço.","A nova regra prova que toda pessoa terá o mesmo acesso.","A mudança tecnológica elimina relações sociais no serviço."]'::jsonb,'"A instituição incorpora uma nova prática e ajusta regras e papéis para organizar seu uso."'::jsonb,'Instituições podem mudar práticas e procedimentos para responder a novas necessidades, preservando ou transformando suas funções e relações.','MEDIUM',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-sociology-institutions-04","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"SOCIOLOGY_EXPLAIN_INSTITUTIONS","purpose":"PRACTICE","difficulty":"MEDIUM","cognitive_process":"COMPARE","context_family":"MUDANCA_INSTITUCIONAL","error_focus":"Tratar instituições como estruturas imutáveis ou presumir efeitos iguais para todos.","remediation_hint":"Identifique o que mudou nas práticas, regras e papéis e quem pode ser afetado de modos diferentes.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-sociology-institutions-04') returning id into v_question_id;
