  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','SOCIOLOGY','INSTITUICOES','SOCIALIZACAO','Uma pesquisa observa que estudantes conhecem regras escolares diferentes conforme suas turmas. Qual investigação ajudaria a explicar como essas expectativas são aprendidas?','["Presumir que todos aprenderam as regras de forma idêntica ao nascer.","Contar apenas os prédios escolares existentes.","Concluir que qualquer diferença resulta de desinteresse pessoal.","Observar interações, orientações, sanções e rotinas pelas quais as regras são comunicadas e interpretadas."]'::jsonb,'"Observar interações, orientações, sanções e rotinas pelas quais as regras são comunicadas e interpretadas."'::jsonb,'Expectativas institucionais são aprendidas em processos de socialização, interações e práticas; observar esses mecanismos evita atribuir diferenças apenas a traços individuais.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-sociology-institutions-05","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"SOCIOLOGY_EXPLAIN_INSTITUTIONS","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"EVALUATE","context_family":"SOCIALIZACAO","error_focus":"Explicar a aprendizagem de normas por características pessoais sem investigar processos sociais.","remediation_hint":"Procure situações e agentes que comunicam, reforçam ou contestam as expectativas.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
