  select 'TECESCOLA','TECESCOLA_V9_AUTHORED_V1','TecEscola V9 authored expansion','SOCIOLOGY','INSTITUICOES','INSTITUICAO_E_DESIGUALDADE','Duas escolas adotam a mesma regra de entrega de trabalhos. Uma oferece biblioteca aberta no contraturno e outra encerra o prédio após as aulas. Como a regra pode produzir experiências diferentes?','["A regra escrita garante resultados idênticos independentemente dos recursos.","Condições institucionais distintas podem afetar as possibilidades reais de cumprir a mesma exigência.","A diferença prova que estudantes de uma escola são menos responsáveis.","A biblioteca não tem relação possível com a realização de trabalhos."]'::jsonb,'"Condições institucionais distintas podem afetar as possibilidades reais de cumprir a mesma exigência."'::jsonb,'Uma norma igual pode interagir com recursos e condições desiguais, influenciando oportunidades sem determinar individualmente o resultado de cada estudante.','HARD',4,'TECESCOLA_V9_AUTHORIAL_V1','{"content_id":"v9-sociology-institutions-07","content_version":"tec-escola-core-v9-question-expansion-v3","primary_skill":"SOCIOLOGY_EXPLAIN_INSTITUTIONS","purpose":"PRACTICE","difficulty":"HARD","cognitive_process":"COMPARE","context_family":"INSTITUICAO_E_DESIGUALDADE","error_focus":"Confundir tratamento formal idêntico com condições materiais iguais.","remediation_hint":"Examine quais recursos e tempos estão disponíveis para diferentes grupos sob a mesma regra.","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","demo_preview_only":true}'::jsonb,true
   where not exists (select 1 from public.learning_question_bank existing where existing.source_type='TECESCOLA_V9_AUTHORED_V1' and existing.metadata->>'content_id'='v9-sociology-institutions-07') returning id into v_question_id;
